export function Card({ title, headingLevel = 3, footer, children }) {
  const Heading = `h${headingLevel}`;
  return (
    <article className="card">
      {title && <Heading className="card__title">{title}</Heading>}
      <div className="card__body">{children}</div>
      {footer && <footer className="card__footer">{footer}</footer>}
    </article>
  );
}

// Varied content, one wrapper.
<Card title="Loops">
  <p>Repeat work with for and while.</p>
</Card>

<Card title="Quick quiz" footer={<button type="button">Submit</button>}>
  <QuizQuestion id="q1" />
  <QuizQuestion id="q2" />
</Card>
```

| children might be | Safe handling |
|---|---|
| one element. | `{children}`. |
| several elements. | `{children}`. |
| a string or number. | `{children}`. |
| nothing. | renders nothing; check with `children != null` if needed. |

